package com.dsha.sidecar.net.rules.native

import com.dsha.sidecar.net.http.HeaderTransforms
import org.junit.Assert.assertEquals
import org.junit.Test
import org.junit.runner.RunWith
import org.junit.runners.Parameterized

/** One JVM case per checked-in fixture generated by original upstream JavaScript. */
@RunWith(Parameterized::class)
class RulePlannerOracleTest(private val id: String, private val fixture: Map<String, Any?>) {
    @Test fun matchesOriginalSelectionAndTransformOutputs() {
        @Suppress("UNCHECKED_CAST")
        val planner = RulePlanner(fixture["layers"] as List<Map<String, Any?>>)
        val input = PlannerJson.obj(fixture["request"])
        val request = RuleRequest(
            input["host"] as String, input["path"] as String, input["method"] as String,
            PlannerJson.obj(input["headers"]), input["scheme"] as String, (input["port"] as Number).toInt(),
        )
        val plan = planner.plan(request)
        val expected = PlannerJson.obj(fixture["expected"]).toMutableMap()
        if (expected["terminal"] != null) {
            val terminal = PlannerJson.obj(expected["terminal"]).toMutableMap()
            // Node merges previously set headers with writeHead headers on the wire.
            terminal["headers"] = PlannerJson.obj(expected["responseSet"]) + PlannerJson.obj(terminal["headers"])
            expected["terminal"] = terminal
            expected["responseSet"] = emptyMap<String, Any?>()
        }
        assertEquals(id, normalized(expected), normalized(project(plan, request)))
    }

    private fun project(plan: RequestPlan, input: RuleRequest): Map<String, Any?> {
        var raw: List<Any?> = listOf("Server", "origin-server", "Vary", "Accept-Encoding")
        val responseSet = linkedMapOf<String, Any?>()
        for (step in plan.responseSteps) {
            when (val action = step.action) {
                is ResponseAction.Cors -> {
                    val transformed = HeaderTransforms.afterOptionsHeaders(
                        input.method, plan.requestHeaders, raw, action.crossOriginResourcePolicy,
                    )
                    raw = transformed.rawHeaders
                    responseSet.putAll(transformed.setHeaders)
                }
                is ResponseAction.Replace -> {
                    val headers = action.headers.toMutableMap()
                    if (action.doDownload) {
                        val filename = Regex("^.*/([^/?]+)/?(\\?.*)?$").find(action.requestPath)?.groupValues?.get(1)
                            ?: "UNKNOWN_FILENAME"
                        headers["content-disposition"] = "attachment; filename=\"$filename\""
                        if (headers["content-type"] == null) headers["content-type"] = "application/octet-stream"
                        if (!action.hasCachePolicy) {
                            listOf("cache-control", "last-modified", "expires").forEach { headers[it] = "[remove]" }
                        }
                    }
                    val transformed = HeaderTransforms.replaceResponseHeaders(raw, headers)
                    raw = transformed.rawHeaders
                    responseSet.putAll(transformed.setHeaders)
                }
                // These are intentionally deferred; the JS generator defers the same operations.
                is ResponseAction.Cache, is ResponseAction.ScriptInjection, is ResponseAction.UnsupportedBody -> Unit
            }
        }
        val route = plan.routeOverride
        val local = plan.localResponse
        return linkedMapOf(
            "selected" to plan.selected.map { source -> linkedMapOf(
                "name" to source.name, "priority" to source.priority, "key" to source.pathPattern,
                "order" to source.order, "matched" to source.pathCaptures, "named" to source.namedPathCaptures,
                "hostMatched" to source.hostnameCaptures, "hostNamed" to source.namedHostnameCaptures,
            ) },
            "executed" to plan.requestSteps.map { it.source.name },
            "route" to mapOf(
                "scheme" to (route?.scheme ?: input.scheme), "host" to (route?.host ?: input.host),
                "port" to (route?.port ?: input.port), "path" to plan.requestPath,
            ),
            "headers" to plan.requestHeaders,
            "serverName" to when (val serverName = plan.tls.serverName) {
                ServerName.Suppress -> ""
                is ServerName.Send -> serverName.host
            },
            "verifyHost" to plan.tls.verificationHost,
            "verify" to (plan.tls.trustMode == TrustMode.VERIFY_CHAIN_AND_HOST),
            "terminal" to local?.let { mapOf("status" to it.status, "headers" to it.headers, "body" to it.body) },
            "retry" to plan.retry?.let { mapOf("times" to it.times, "statuses" to it.statuses, "methods" to it.methods) },
            "doDownload" to plan.doDownload,
            "responseRaw" to raw,
            "responseSet" to responseSet.filterKeys { !it.startsWith("DS-") },
        )
    }

    private fun normalized(value: Any?): Any? = when (value) {
        is Number -> value.toDouble()
        is Map<*, *> -> value.mapValues { normalized(it.value) }
        is List<*> -> value.map(::normalized)
        else -> value
    }

    companion object {
        @JvmStatic
        @Parameterized.Parameters(name = "{0}")
        fun fixtures(): List<Array<Any?>> = UpstreamRuleOracle.cases.map { arrayOf(it["id"], it) }
    }
}
